async function readQuickMembershipStatus(profileRequestGeneration = profileGeneration) {
  const generation = (readQuickMembershipStatus.generation || 0) + 1;
  readQuickMembershipStatus.generation = generation;
  const minimalExpiry = document.getElementById("minimal-member-expiry");
  if (minimalExpiry) minimalExpiry.textContent = "\u2014";
  const staleDiag = document.getElementById("minimal-member-diag");
  if (staleDiag) staleDiag.textContent = "";
  try {
    // Membership has no archive/contact scan or points-ledger decorator.
    // Let its canonical snapshot render while the full profile is loading.
    const response = await memberApiFetch("/api/member/app/membership", { credentials:"same-origin", cache:"no-store", headers:{ accept:"application/json" } });
    const body = await response.json().catch(() => null);
    if (generation !== readQuickMembershipStatus.generation || profileRequestGeneration !== profileGeneration) return;
    if (!response.ok || !body || body.ok === false) {
      // Status code and state only; no member data. Shows why the card stayed empty.
      const diag = document.getElementById("minimal-member-diag");
      if (diag) diag.textContent = "\u0E2D\u0E48\u0E32\u0E19\u0E02\u0E49\u0E2D\u0E21\u0E39\u0E25\u0E2A\u0E21\u0E32\u0E0A\u0E34\u0E01\u0E44\u0E21\u0E48\u0E2A\u0E33\u0E40\u0E23\u0E47\u0E08 (" + response.status + (body && typeof body.state === "string" ? " " + body.state.slice(0, 24) : "") + ")";
      return;
    }
    const membership = body.data && typeof body.data === "object" ? body.data : body;
    // Membership may be fully verified; never expose a second partial-data
    // card merely because an expiry date arrived. Only the authoritative
    // history-preview recovery lane may reveal the folded history note.
    const supportedExpiry = safeDate(membership.expiresAt || membership.renewalDueAt);
    if (minimalExpiry && supportedExpiry) minimalExpiry.textContent = shortDate(supportedExpiry);
    if (!supportedExpiry) {
      // Field presence only, never values: shows why the expiry stayed empty.
      const diagMissing = document.getElementById("minimal-member-diag");
      if (diagMissing) diagMissing.textContent = "\u0E44\u0E21\u0E48\u0E1E\u0E1A\u0E27\u0E31\u0E19\u0E2B\u0E21\u0E14\u0E2D\u0E32\u0E22\u0E38 (" + response.status + " status=" + String(membership.status || membership.lifecycle || "-").slice(0, 16)
        + " expiresAt=" + (membership.expiresAt ? "invalid" : "empty") + " renewal=" + (membership.renewalDueAt ? "invalid" : "empty") + ")";
    }
    const labels = { public_member:"Member", elite:"Elite", red_card:"Red Card", trial_7d:"7 Days", standard:"Standard", premium:"Premium", vip:"VIP", svip:"SVIP", black_card:"Black Card" };
    const level = String(membership.level || "").trim().toLowerCase();
    const tierNode = document.getElementById("profile-tier");
    const statusNode = document.getElementById("profile-status");
    if (tierNode && membership.levelVerified === true && labels[level]) tierNode.textContent = labels[level];
    const status = String(membership.status || membership.lifecycle || "").trim();
    if (statusNode && ["active", "grace", "expired", "blocked", "suspended", "revoked", "pending_review", "checking"].includes(status)) {
      const expiry = safeDate(membership.expiresAt || membership.renewalDueAt);
      statusNode.textContent = membershipStatus(status) + (expiry ? " \xB7 \u0E16\u0E36\u0E07 " + shortDate(expiry) : "");
    }
  } catch (error) {
    if (profileRequestGeneration !== profileGeneration) return;
    const diagError = document.getElementById("minimal-member-diag");
    if (diagError) diagError.textContent = "\u0E2D\u0E48\u0E32\u0E19\u0E02\u0E49\u0E2D\u0E21\u0E39\u0E25\u0E2A\u0E21\u0E32\u0E0A\u0E34\u0E01\u0E1C\u0E34\u0E14\u0E1E\u0E25\u0E32\u0E14 (" + String(error && error.name || "error").slice(0, 24) + ")";
  }
}

