}

function setProfileRetry(visible) {
  let notice = document.getElementById("member-profile-retry");
  if (!visible) { notice?.remove(); return; }
  if (notice) return;
  notice = document.createElement("div");
  notice.id = "member-profile-retry";
  const message = document.createElement("p");
  message.setAttribute("role", "status");
  message.textContent = "ตอนนี้โหลดโปรไฟล์ไม่ได้ครับ ลองอีกครั้งได้โดยไม่ต้องยืนยัน LINE ใหม่";
  const retry = document.createElement("button");
  retry.type = "button";
  retry.textContent = "ลองโหลดโปรไฟล์อีกครั้ง";
  retry.addEventListener("click", async () => {
    if (retry.disabled) return;
    retry.disabled = true;
    try { await readProfile({ silent: true }); }
    finally { retry.disabled = false; }
  });
  notice.append(message, retry);
  appStatus?.before(notice);
}

async function readProfile({ hydrate = true, silent = false } = {}) {
  const generation = ++profileGeneration;
  // Do not leave the prior Client's details visible while a new session is checked.
  hideMemberProfile();
  try {
    const response = await memberApiFetch(CONFIG.profileEndpoint, { method: "GET", credentials: "same-origin", headers: { "accept": "application/json" } });
    const payload = await response.json().catch(() => null);
    if (generation !== profileGeneration) return null;
    if (!response.ok || !payload || payload.ok !== true) {
      clearMemberProfile({ silent });
      setProfileRetry(response.status === 503);
      return null;
    }
    setProfileRetry(false);
    renderProfile(payload.data || {}, response.headers.get("x-mmd-member-display-authority") || "", response.headers.get("x-mmd-brand-authority") || "");
    renderCustomerContact(payload.data || {});
    void personalMainUI.load();
    void readQuickMembershipStatus(generation);
    void readOwnHistoryPreview(generation);
    if (hydrate) await hydrateMemberHome();
    return payload.data || {};
  } catch {
    if (generation === profileGeneration) clearMemberProfile({ silent });
    return null;
  }
}

function requestId() {
  const uuid = typeof crypto?.randomUUID === "function" ? crypto.randomUUID().replace(/-/g, "") : String(Date.now()) + Math.random().toString(36).slice(2);
  return "req_" + uuid;
}

const customerRequestSession = (() => { try { return window.sessionStorage; } catch { return null; } })();
const customerRequestStoragePrefix = "mmd.customer_request.pending.v1.";
function customerRequestStorageKey(kind, token = "default") { return customerRequestStoragePrefix + kind + "." + token; }
function pendingRequestId(kind, token = "default") {
  const key = customerRequestStorageKey(kind, token);
  const stored = customerRequestSession?.getItem(key) || "";
  if (/^req_[A-Za-z0-9_-]{12,80}$/.test(stored)) return stored;
  const next = requestId(); customerRequestSession?.setItem(key, next); return next;
}
function clearPendingRequest(kind, token = "default") { customerRequestSession?.removeItem(customerRequestStorageKey(kind, token)); }
function terminalClientError(response) { return response.status >= 400 && response.status < 500 && ![408, 409, 425, 429].includes(response.status); }
async function opaqueStorageToken(value) {
  const input = new TextEncoder().encode(String(value).slice(0, 500));
  if (crypto?.subtle) {
    const digest = await crypto.subtle.digest("SHA-256", input);
    return Array.from(new Uint8Array(digest)).slice(0, 12).map((byte) => byte.toString(16).padStart(2, "0")).join("");
  }
  let hash = 2166136261; for (const byte of input) { hash ^= byte; hash = Math.imul(hash, 16777619); }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

